주의를 지키기 위한 최소한의 의무”라고 거듭 강조했다. [스트레이트뉴스 경남=김태양 기자] 저작권자 © 스트레이트뉴스 무단전재 및 재배포 금지 김태양 기자 kim134114@naver.com 다른기사 보기 SNS 기사보내기 페이스북(으)로 기사보내기 트위터(으)로 기사보내기 카카오톡(으)로 기사보내기 URL복사(으)로 기사보내기 이메일(으)로 기사보내기 다른 공유 찾기 기사스크랩하기 $(document).ready(function(e) { $('.scrap-btn').on('click', function(e) { var idxno = $(this).data('idxno'); if(confirm("기사를 스크랩 하시겠습니까?")){ $.ajax({ type: 'post', dataType: 'json', url: '/news/articleScrap.ajax.php', data: {'tp':'A', 'idxno':idxno}, success: function(data) { alert(data[1]); }, error: function(error, request) { alert('error!!!'); console.log("code:"+request.status+"\n"+"message:"+request.responseText+"\n"+"error:"+error); } }); } }); }); $(document).ready(function(e) { $('.scrap-btn').on('click', function(e) { var idxno = $(this).data('idxno'); if(confirm("기사를 스크랩 하시겠습니까?")){ $.ajax({ type: 'post', dataType: 'json', url: '/news/articleScrap.ajax.php', data: {'tp':'A', 'idxno':idxno}, success: function(data) { alert(data[1]); }, error: function(error, request) { alert('error!!!'); console.log("code:"+request.status+"\n"+"message:"+request.responseText+"\n"+"error:"+error); } }); } }); }); 당신만 안 본 뉴스 #skin-9 > .item:not(:first-child) {margin-top:12px} [단독] “전환배치인가 퇴출인가”…데이원컴퍼니 논란 확산 LS·대한전선, 수주잔고 10조 고지 돌파…"장기 슈퍼사이클 진입" 기업은행, ‘중소기업 동반성장’ 지속가능 빛나 "진주 경제 살릴 적임자"… 청년·소상공인단체 박명균 예비후보 지지 [르포] '강남·여의도·용산 다 20분"...공시촌 노량진, 하이엔드로 상전벽해 [단독] 한화투자, ‘디지털자산 전문증권사’ 전환 속도 [살집 말집] 옥정중앙역 대방 디에트르, '넘사벽' 최고가 vs 대방 '억울해' #skin-10 > .item {position:relative;margin-top:16px}
